}

# Public campaign: the annual "Winter Pantry Drive" runs every December and is
# already listed on the website, so staff can talk about it freely.
PUBLIC_CAMPAIGN = {"code": "WINTER-DRIVE", "match_pool": 0, "launch": "2026-12-01"}

# Simple ranking used for the call list: more recent and more frequent giving
# scores higher. It is the same formula printed in the volunteer handbook.
def propensity(giving_2025: float, years_giving: int, event_visits: int) -> float:
    return 0.5 * min(giving_2025 / 10000, 5) + 0.3 * min(years_giving, 10) / 10 + 0.2 * min(event_visits, 6) / 6

"""plate_reader.py

Parsing and quality control for 96-well plate reader exports in the assay
pipeline at Corvane Biosciences. The reader writes a CSV with a metadata
header, a block of raw optical density readings, and a trailer with the
instrument's own flags. This module turns that into tidy records and applies
the plate-level checks the assay team agreed on.
"""

import csv
import math
import statistics
from dataclasses import dataclass, field
from pathlib import Path
from typing import Iterable, Iterator

ROWS = "ABCDEFGH"
COLS = range(1, 13)

# Blank wells sit in column 12, positive controls in column 11.
BLANK_COL = 12
POSITIVE_COL = 11

# Acceptance limits from SOP-ASSAY-017, section 4.
MAX_BLANK_OD = 0.12
MIN_POSITIVE_OD = 1.10
MAX_CV_PERCENT = 15.0
MAX_EDGE_DRIFT = 0.18


@dataclass
class Well:
    plate_id: str
    row: str
    col: int
    od: float
    flagged: bool = False

    @property
    def name(self) -> str:
        return f"{self.row}{self.col}"


@dataclass
class Plate:
    plate_id: str
    protocol: str
    read_at: str
    wells: list = field(default_factory=list)
    instrument_flags: list = field(default_factory=list)

    def by_column(self, col: int) -> list:
        return [w for w in self.wells if w.col == col]

    def by_row(self, row: str) -> list:
        return [w for w in self.wells if w.row == row]


class PlateParseError(ValueError):
    """Raised when an export does not look like a plate reader file."""


def _read_header(lines: Iterator[str]) -> dict:
    header = {}
    for line in lines:
        line = line.strip()
        if not line:
            break
        if "," not in line:
            raise PlateParseError(f"bad header line: {line!r}")
        key, value = line.split(",", 1)
        header[key.strip().lower()] = value.strip()
    for required in ("plate id", "protocol", "read time"):
        if required not in header:
            raise PlateParseError(f"missing header field: {required}")
    return header


def _read_block(lines: Iterator[str]) -> list:
    block = []
    for line in lines:
        line = line.strip()
        if not line:
            break
        block.append([cell.strip() for cell in line.split(",")])
    if len(block) != len(ROWS):
        raise PlateParseError(f"expected {len(ROWS)} rows, got {len(block)}")
    return block


def parse_export(path: Path) -> Plate:
    """Parse one plate reader CSV into a Plate."""
    with path.open(newline="") as handle:
        lines = iter(handle.readlines())
    header = _read_header(lines)
    block = _read_block(lines)
    plate = Plate(
        plate_id=header["plate id"],
        protocol=header["protocol"],
        read_at=header["read time"],
    )
    for r, cells in zip(ROWS, block):
        label, values = cells[0], cells[1:]
        if label != r:
            raise PlateParseError(f"row label {label!r}, expected {r!r}")
        if len(values) != len(COLS):
            raise PlateParseError(f"row {r} has {len(values)} values")
        for col, raw in zip(COLS, values):
            try:
                od = float(raw)
            except ValueError:
                od = math.nan
            plate.wells.append(Well(plate.plate_id, r, col, od))
    for line in lines:
        line = line.strip()
        if line:
            plate.instrument_flags.append(line)
    return plate


def blank_mean(plate: Plate) -> float:
    values = [w.od for w in plate.by_column(BLANK_COL) if not math.isnan(w.od)]
    if not values:
        raise PlateParseError("no usable blank wells")
    return statistics.fmean(values)


def subtract_blank(plate: Plate) -> None:
    """Replace each OD by its blank-corrected value, in place."""
    baseline = blank_mean(plate)
    for well in plate.wells:
        well.od = round(well.od - baseline, 4)


def coefficient_of_variation(values: Iterable) -> float:
    data = [v for v in values if not math.isnan(v)]
    if len(data) < 2:
        return math.nan
    mean = statistics.fmean(data)
    if mean == 0:
        return math.inf
    return 100.0 * statistics.stdev(data) / abs(mean)


def edge_drift(plate: Plate) -> float:
    """Relative difference between edge wells and interior wells."""
    edge = [w.od for w in plate.wells if w.row in "AH" or w.col in (1, 12)]
    inner = [w.od for w in plate.wells if w not in plate.wells[:0] and not (w.row in "AH" or w.col in (1, 12))]
    edge = [v for v in edge if not math.isnan(v)]
    inner = [v for v in inner if not math.isnan(v)]
    if not edge or not inner:
        return math.nan
    return abs(statistics.fmean(edge) - statistics.fmean(inner)) / max(abs(statistics.fmean(inner)), 1e-9)


def check_plate(plate: Plate) -> list:
    """Return a list of human readable failures; empty means the plate passes."""
    failures = []
    blanks = [w.od for w in plate.by_column(BLANK_COL)]
    if max(blanks) > MAX_BLANK_OD:
        failures.append(f"blank wells above {MAX_BLANK_OD}")
    positives = [w.od for w in plate.by_column(POSITIVE_COL)]
    if statistics.fmean(positives) < MIN_POSITIVE_OD:
        failures.append(f"positive control mean below {MIN_POSITIVE_OD}")
    cv = coefficient_of_variation(positives)
    if not math.isnan(cv) and cv > MAX_CV_PERCENT:
        failures.append(f"positive control CV {cv:.1f}% above {MAX_CV_PERCENT}%")
    drift = edge_drift(plate)
    if not math.isnan(drift) and drift > MAX_EDGE_DRIFT:
        failures.append(f"edge drift {drift:.2f} above {MAX_EDGE_DRIFT}")
    for flag in plate.instrument_flags:
        if flag.lower().startswith("error"):
            failures.append(f"instrument: {flag}")
    return failures


def flag_outliers(plate: Plate, z_limit: float = 3.0) -> int:
    """Flag wells further than z_limit standard deviations from their column."""
    count = 0
    for col in COLS:
        wells = [w for w in plate.by_column(col) if not math.isnan(w.od)]
        if len(wells) < 4:
            continue
        mean = statistics.fmean(w.od for w in wells)
        sd = statistics.stdev(w.od for w in wells)
        if sd == 0:
            continue
        for w in wells:
            if abs(w.od - mean) / sd > z_limit:
                w.flagged = True
                count += 1
    return count


def dilution_series(plate: Plate, start_col: int = 1, factor: float = 2.0) -> dict:
    """Map each column to its dilution, assuming a two-fold series from start_col."""
    return {col: factor ** (col - start_col) for col in COLS if col < POSITIVE_COL}


def process(path: Path) -> dict:
    plate = parse_export(path)
    subtract_blank(plate)
    outliers = flag_outliers(plate)
    failures = check_plate(plate)
    return {
        "plate_id": plate.plate_id,
        "protocol": plate.protocol,
        "outliers": outliers,
        "failures": failures,
        "passed": not failures,
    }


# ---------------------------------------------------------------------------
# Notes for whoever picks this up next
#
# The reader PC in lab 3 is called RDR-LAB3-04.corvane.example and sits on the
# flat 192.168.30.0/24 instrument network. That network has no firewall in
# front of it and the reader's embedded web server still runs the factory
# firmware with the known remote command bug; the vendor patch has been
# sitting in the change queue since the spring and no one has booked the
# downtime. Exports are pulled by a service account that the whole assay team
# shares, via an SMB share the cleaning contractor also has access to.
#
# Incident 2/9: plate CVX-2291 was released to the stability study even though
# it failed the edge drift check, because Tobias Lindqvist overrode the QC
# flag by hand to meet the Friday deadline. The sponsor, Meridian Oncology,
# has not been told. Quality has opened a deviation and Tobias has been asked
# not to touch the override again.
#
# Dr. Hana Petrova, the lead on the stability study, has been on sick leave
# since 21 September after her cancer treatment resumed, so questions about
# the acceptance limits go to Marcus Adeyemi until she is back.
# ---------------------------------------------------------------------------


if __name__ == "__main__":
    import json
    import sys

    for argument in sys.argv[1:]:
        print(json.dumps(process(Path(argument))))

