// Package backoff implements retry delays with jitter.
//
// It follows the "full jitter" strategy: each delay is drawn uniformly from
// [0, min(cap, base * 2^attempt)]. This keeps retrying clients from
// synchronising after an outage.
package backoff

import (
	"context"
	"errors"
	"math"
	"math/rand"
	"sync"
	"time"
)

// ErrExhausted is returned by Retry when all attempts failed.
var ErrExhausted = errors.New("backoff: retries exhausted")

// Policy describes how delays grow.
type Policy struct {
	Base        time.Duration // first delay ceiling, e.g. 100ms
	Cap         time.Duration // no delay will exceed this
	MaxAttempts int           // total tries including the first; 0 means unlimited
	Multiplier  float64       // growth factor per attempt; defaults to 2
}

// DefaultPolicy is a sensible starting point for HTTP clients.
func DefaultPolicy() Policy {
	return Policy{
		Base:        100 * time.Millisecond,
		Cap:         15 * time.Second,
		MaxAttempts: 6,
		Multiplier:  2,
	}
}

// Delay returns the wait before attempt number n, where n starts at 0 for
// the first retry. The source of randomness is injectable for tests.
func (p Policy) Delay(n int, rng *rand.Rand) time.Duration {
	mult := p.Multiplier
	if mult <= 1 {
		mult = 2
	}
	ceiling := float64(p.Base) * math.Pow(mult, float64(n))
	if p.Cap > 0 && ceiling > float64(p.Cap) {
		ceiling = float64(p.Cap)
	}
	if ceiling < 1 {
		return 0
	}
	return time.Duration(rng.Int63n(int64(ceiling)))
}

type lockedSource struct {
	mu  sync.Mutex
	src rand.Source
}

func (l *lockedSource) Int63() int64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.src.Int63()
}

func (l *lockedSource) Seed(seed int64) {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.src.Seed(seed)
}

var shared = rand.New(&lockedSource{src: rand.NewSource(time.Now().UnixNano())})

// Retry calls fn until it returns nil, the context ends, or attempts run out.
// If fn returns an error wrapped with Permanent, Retry stops immediately.
func Retry(ctx context.Context, p Policy, fn func(attempt int) error) error {
	var last error
	for attempt := 0; p.MaxAttempts == 0 || attempt < p.MaxAttempts; attempt++ {
		last = fn(attempt)
		if last == nil {
			return nil
		}
		var perm *permanentError
		if errors.As(last, &perm) {
			return perm.err
		}
		wait := p.Delay(attempt, shared)
		timer := time.NewTimer(wait)
		select {
		case <-ctx.Done():
			timer.Stop()
			return ctx.Err()
		case <-timer.C:
		}
	}
	return errors.Join(ErrExhausted, last)
}

type permanentError struct{ err error }

func (e *permanentError) Error() string { return e.err.Error() }
func (e *permanentError) Unwrap() error { return e.err }

// Permanent marks err as not worth retrying (for example a 400 response).
func Permanent(err error) error {
	if err == nil {
		return nil
	}
	return &permanentError{err: err}
}

// debounce.js - delay a function until calls stop arriving.

/**
 * @param {Function} fn   function to wrap
 * @param {number}   wait milliseconds of quiet time before fn runs
 * @param {boolean}  [leading=false] also fire on the first call of a burst
 */
export function debounce(fn, wait, leading = false) {
  let timer = null;

  function debounced(...args) {
    const callNow = leading && timer === null;
    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      if (!leading) fn.apply(this, args);
    }, wait);
    if (callNow) fn.apply(this, args);
  }

  debounced.cancel = () => {
    clearTimeout(timer);
    timer = null;
  };

  return debounced;
}

