/** Splits a string into chunks of at most {@code size} characters. */
public final class Chunker {
    private Chunker() {}

    public static List<String> split(String s, int size) {
        if (size <= 0) {
            throw new IllegalArgumentException("size must be positive");
        }
        List<String> parts = new ArrayList<>();
        for (int i = 0; i < s.length(); i += size) {
            parts.add(s.substring(i, Math.min(s.length(), i + size)));
        }
        return parts;
    }

    public static void main(String[] args) {
        System.out.println(split("abcdefghij", 4)); // [abcd, efgh, ij]
    }
}

