#include <stdio.h>
#include <stdlib.h>

typedef struct node {
    int value;
    struct node *next;
} node;

static node *push_front(node *head, int value) {
    node *n = malloc(sizeof *n);
    if (!n) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    n->value = value;
    n->next = head;
    return n;
}

static node *reverse(node *head) {
    node *prev = NULL;
    while (head) {
        node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

int main(void) {
    node *list = NULL;
    for (int i = 1; i <= 5; i++) list = push_front(list, i * i);
    list = reverse(list);
    for (node *p = list; p; p = p->next) printf("%d ", p->value);
    putchar('\n');
    return 0;
}

