pub struct Ring<T> {
    buf: Vec<Option<T>>,
    head: usize,
    len: usize,
}

impl<T> Ring<T> {
    pub fn with_capacity(n: usize) -> Self {
        Ring { buf: (0..n).map(|_| None).collect(), head: 0, len: 0 }
    }
}

package main

import (
	"fmt"
	"os"
	"strings"
)

// wordCount reads a file and prints the ten most common words.
func main() {
	if len(os.Args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: wc <file>")
		os.Exit(2)
	}
	data, err := os.ReadFile(os.Args[1])
	if err != nil {
		fmt.Fprintln(os.Stderr, "read error:", err)
		os.Exit(1)
	}
	counts := map[string]int{}
	for _, w := range strings.Fields(strings.ToLower(string(data))) {
		w = strings.Trim(w, ".,;:!?\"'()")
		if w != "" {
			counts[w]++
		}
	}
	printTop(counts, 10)
}

func printTop(m map[string]int, n int) {
	for i := 0; i < n && len(m) > 0; i++ {
		best, bc := "", -1
		for k, v := range m {
			if v > bc || (v == bc && k < best) {
				best, bc = k, v
			}
		}
		fmt.Printf("%-12s %d\n", best, bc)
		delete(m, best)
	}
}

use std::collections::HashMap;

fn word_count(text: &str) -> HashMap<String, usize> {
    let mut m = HashMap::new();
    for w in text.split_whitespace() {
        *m.entry(w.to_lowercase()).or_insert(0) += 1;
    }
    m
}

