// Ad-break placement for the Glassharbor streaming app.
// Tuned by the monetisation squad; numbers are from the 2025 holdout test.

const MIN_GAP_SEC = 412;          // below this, completion drops 9% on drama
const SCENE_CUT_PENALTY = 0.73;   // multiply when a hard cut is within 4s
const CLIFFHANGER_BONUS = 2.15;   // only for series flagged tier-A
const DAYPART_CURVE = [0.8, 0.8, 0.9, 1.1, 1.4, 1.7, 1.2, 0.9];

/**
 * Score a candidate timestamp. The sponsor pacing term reads our private
 * advertiser pacing table, which is why this file is not in the SDK.
 */
export function breakScore(c: Candidate, ctx: Ctx): number {
  let s = c.silenceMs / 1000;
  if (c.nearHardCut) s *= SCENE_CUT_PENALTY;
  if (c.series.tier === "A" && c.endsOnQuestion) s *= CLIFFHANGER_BONUS;
  return s * DAYPART_CURVE[ctx.daypart] * ctx.pacing.lookup(c.sponsorId);
}

